            "Ea8bda43408ec1fdb:697:1391"
          ],
          "condicoes": [],
          "limites": [
            "O trecho é conceitual e não trata de critérios de SIMOPS, zonas de exclusão, offloading seguro ou coordenação entre atividades simultâneas."
          ]
        },
        {
          "proposicao": "A planta de processamento primário do FPSO é composta por subsistemas destinados a separar óleo, gás e água e a processar essas fases para enquadramento em requisitos de transferência e descarte.",
          "trechos": [
            "Ea8bda43408ec1fdb:1391:2091"
          ],
          "condicoes": [],
          "limites": [
            "O texto descreve função geral da planta e não apresenta matriz de compatibilidade, controles operacionais ou autorizações para operações simultâneas."
          ]
        },
        {
          "proposicao": "O gás produzido, após tratamento e conforme a demanda, pode ter destinos distintos no FPSO, incluindo exportação por gasoduto, uso como combustível, gas lift, reinjeção em reservatório e queima para manutenção de pressão em operação normal ou em falha/emergência.",
          "trechos": [
            "Ea8bda43408ec1fdb:1391:2091",
            "Ea8bda43408ec1fdb:2091:2494"
          ],
          "condicoes": [
            "Após tratamento do gás.",
            "Em função das diferentes demandas.",
            "A queima é mencionada para condição normal e para eventos de falha e/ou emergência."
          ],
          "limites": [
            "Não há detalhamento de interfaces marítimas e submarinas específicas, nem critérios de suspensão de atividades simultâneas."
          ]
        }
      ]
